{
  "groups": [
    {
      "group_id": "low_rate_shock",
      "rule": "rate_type == 'fixed' and origination_year <= 2021 and mortgage_rate_pct < 3.0",
      "rationale": "Borrowers with low fixed rates from previous years face significant payment increases at renewal, making them highly sensitive to retention offers."
    },
    {
      "group_id": "vulnerable_renters",
      "rule": "occupancy_type == 'rental' and household_income_cad < 75000",
      "rationale": "Investors or owners of rental properties with lower incomes are more exposed to cash flow instability during rising interest rate environments."
    },
    {
      "group_id": "high_debt_young_families",
      "rule": "n_children >= 2 and other_debt_payment_monthly_cad > 400 and household_income_cad < 100000",
      "rationale": "Large households with existing debt and moderate income have limited financial slack to absorb higher monthly mortgage payments."
    },
    {
      "group_id": "credit_constrained",
      "rule": "credit_score_band in ['below_600', '600_659'] and insured_flag == False",
      "rationale": "Uninsured borrowers with lower credit scores have reduced mobility to refinance with other lenders and are more likely to be retained."
    },
    {
      "group_id": "prime_uninsured",
      "rule": "credit_score_band == '720_plus' and insured_flag == False and mortgage_balance_cad > 400000",
      "rationale": "High-credit borrowers with substantial balances are the primary targets for competitor acquisition and require proactive retention."
    },
    {
      "group_id": "distressed_variable",
      "rule": "rate_type == 'variable' and payment_structure == 'adjustable_payment' and credit_utilization_pct > 45.0",
      "rationale": "Variable rate borrowers with adjustable payments and high credit utilization are already experiencing payment shocks and financial stress."
    },
    {
      "group_id": "affluent_investors",
      "rule": "has_investments == True and household_income_cad >= 150000",
      "rationale": "High-income households with investments represent a stable segment that prioritizes relationship value and service over rate-seeking."
    },
    {
      "group_id": "remote_digital_adopters",
      "rule": "channel == 'digital' and has_advisor == False",
      "rationale": "Borrowers who interact through digital channels without an assigned advisor are more likely to switch lenders based on self-serve rate comparisons."
    }
  ]
}
